'use strict'

// Regression test for https://github.com/nodejs/undici/issues/5404
//
// HTTP/2 streams complete out of order. The H2 completion path used to do:
//   client[kQueue][client[kRunningIdx]++] = null
// which assumes in-order completion. When a later stream completed first, the
// slot of a still-running request was cleared and kRunningIdx moved past it, so
// the running request was lost from the queue while an already-completed request
// was left classified as running. Destroy/error cleanup then errored completed
// requests, tripped over the `null` slots, and never errored the running one.

const { test, after } = require('node:test')
const assert = require('node:assert')
const { createSecureServer } = require('node:http2')
const { once } = require('node:events')
const { setTimeout: sleep } = require('node:timers/promises')

const pem = require('@metcoder95/https-pem')

const { Client } = require('..')
const { kQueue, kRunningIdx, kPendingIdx, kRunning } = require('../lib/core/symbols')

async function createH2Server (t) {
  const server = createSecureServer(await pem.generate({ opts: { keySize: 2048 } }))

  server.on('stream', (stream, headers) => {
    stream.on('error', () => {})

    if (headers[':path'] === '/slow') {
      // Keep the stream open until the client goes away.
      return
    }

    stream.respond({ ':status': 200 })
    stream.end('fast')
  })

  after(() => server.close())
  await once(server.listen(0), 'listening')

  return server
}

function createClient (server) {
  const client = new Client(`https://localhost:${server.address().port}`, {
    connect: { rejectUnauthorized: false },
    allowH2: true
  })

  after(() => client.destroy())

  return client
}

test('h2: out-of-order completion keeps the running request in the queue', async (t) => {
  const server = await createH2Server(t)
  const client = createClient(server)

  const slow = client.request({ path: '/slow', method: 'GET' })
  // Make sure the slow request is dispatched (and therefore enqueued as
  // running) before the fast one.
  await sleep(100)

  const slowRequest = client[kQueue][client[kRunningIdx]]
  assert.notStrictEqual(slowRequest, null)
  assert.strictEqual(slowRequest.path, '/slow')

  const fast = await client.request({ path: '/fast', method: 'GET' })
  assert.strictEqual(fast.statusCode, 200)
  await fast.body.dump()

  // The fast request completed while the slow one is still running.
  const running = client[kQueue].slice(client[kRunningIdx], client[kPendingIdx])

  assert.deepStrictEqual(running, [slowRequest], 'running section must only hold the still-running request')
  assert.strictEqual(client[kRunning], 1)

  slow.catch(() => {})
})

test('h2: destroying after out-of-order completion errors the running request', async (t) => {
  const server = await createH2Server(t)
  const client = createClient(server)

  const clientErrors = []
  client.on('error', (err) => clientErrors.push(err))

  const slow = client.request({ path: '/slow', method: 'GET' })
  await sleep(100)

  const fastResponses = []
  for (let i = 0; i < 2; i++) {
    const response = await client.request({ path: '/fast', method: 'GET' })
    fastResponses.push(await response.body.text())
  }

  assert.deepStrictEqual(fastResponses, ['fast', 'fast'])

  const err = new Error('destroyed')
  await client.destroy(err)

  await assert.rejects(slow, /destroyed|closed|aborted/i)
  assert.deepStrictEqual(clientErrors, [], 'client must not emit errors for completed or missing requests')
})

