function writeH2 (client, request) {
  const headersTimeout = request.headersTimeout ?? client[kHeadersTimeout]
  const bodyTimeout = request.bodyTimeout ?? client[kBodyTimeout]
  const session = client[kHTTP2Session]
  const { method, path, host, upgrade, expectContinue, signal, protocol, headers: reqHeaders } = request
  let { body } = request

  if (upgrade != null && upgrade !== 'websocket') {
    util.errorRequest(client, request, new InvalidArgumentError(`Custom upgrade "${upgrade}" not supported over HTTP/2`))
    return false
  }

  const headers = buildRequestHeaders(reqHeaders)

  /** @type {import('node:http2').ClientHttp2Stream} */
  let stream = null

  headers[HTTP2_HEADER_AUTHORITY] = host || client[kHostAuthority]
  headers[HTTP2_HEADER_METHOD] = method

  let requestFinalized = false
  const finalizeRequest = () => {
    if (requestFinalized) {
      return
    }

    requestFinalized = true

    // HTTP/2 multiplexes requests on independent streams, so they can complete
    // out of order and the finalized request is not necessarily the one at
    // kRunningIdx. Remove the request itself from the running section of the
    // queue so that the other running requests, and their relative order, are
    // preserved.
    const queue = client[kQueue]
    const idx = queue.indexOf(request, client[kRunningIdx])

    if (idx !== -1 && idx < client[kPendingIdx]) {
      queue.splice(idx, 1)
      client[kPendingIdx] -= 1
    }

    // Otherwise the request is not part of the running section: either it has
    // already been removed, it has been requeued for a retry, or it has not been
    // promoted from pending yet (a synchronous abort from writeH2, in which case
    // writeH2 returns false and _resume removes it from the queue).

    client[kResume]()
  }

  const abort = (err) => {
    if (request.aborted || request.completed) {
      return
    }

    err = err || new RequestAbortedError()

    util.errorRequest(client, request, err)

    if (stream != null) {
      clearRequestStream(request)

      // On Abort, we close the stream to send RST_STREAM frame
      stream.close()

      // We remove the request from the running section of the queue
      client[kOnError](err)
      finalizeRequest()
    }

    // We do not destroy the socket as we can continue using the session
    // the stream gets destroyed and the session remains to create new streams
    util.destroy(body, err)
  }

  const requestStream = (headers, options) => {
    try {
      return session.request(headers, options)
    } catch (err) {
      if (err?.code === 'ERR_HTTP2_INVALID_SESSION') {
        const wrappedErr = new SocketError(err.message, util.getSocketInfo(session[kSocket]))
        wrappedErr.cause = err
        session[kError] = wrappedErr
        resetHttp2Session(session, wrappedErr)
        requeueUnsentRequest(client, request)

        return null
      }

      const wrappedErr = new InformationalError(err.message, { cause: err })
      session[kError] = wrappedErr
      session[kSocket][kError] = wrappedErr

      session.destroy(wrappedErr)
      util.destroy(session[kSocket], wrappedErr)
      abort(wrappedErr)

      return null
    }
  }

  try {
    // We are already connected, streams are pending.
    // We can call on connect, and wait for abort
    request.onRequestStart(abort, null)
  } catch (err) {
    util.errorRequest(client, request, err)
  }

  if (request.aborted) {
    return false
  }

  if (upgrade || method === 'CONNECT') {
    session.ref()

    const upgradeState = {
      abort,
      finalizeRequest,
      request,
      headersTimeout,
      bodyTimeout,
      responseReceived: false,
      session,
      stream: null
